CREATE TABLE atlys_dataset.coupon_field_shown (`id` FixedString(32) COMMENT 'event id, 32-char hex' CODEC(ZSTD(1)), `timestamp` DateTime64(3, 'UTC') COMMENT 'event time, ms precision' CODEC(Delta(8), ZSTD(1)), `device_type` LowCardinality(String) COMMENT 'ios/Desktop/web-user-b2c/android, 4 values', `os` LowCardinality(String) DEFAULT '' COMMENT '5 values; 6.2% empty, bucket as unknown', `app_version` LowCardinality(String) COMMENT '3 values', `geoip_country_code` LowCardinality(String) COMMENT '7 values', `city` LowCardinality(String) COMMENT '7 values', `client_lib` LowCardinality(String) COMMENT 'mobile-rn or web-js', `user_id` String COMMENT 'traveller id, 28 chars, joins all tables' CODEC(ZSTD(1)), `application_id` FixedString(32) COMMENT 'funnel join key across coupon events' CODEC(ZSTD(1)), `destination` LowCardinality(String) COMMENT '14 values, ISO-2 uppercase', `cart_value` Decimal(18, 2) COMMENT 'cart total in accompanying currency, range 1501-9000', `currency` LowCardinality(String) COMMENT '7 values, never aggregate across currencies', INDEX idx_user_id user_id TYPE bloom_filter(0.01) GRANULARITY 4) ENGINE = SharedMergeTree('/clickhouse/tables/{uuid}/{shard}', '{replica}') PARTITION BY toYYYYMM(timestamp) ORDER BY (device_type, destination, application_id, timestamp) SETTINGS index_granularity = 8192 COMMENT 'coupon_field_shown: field renders, funnel step 1 of promo checkout (spec 06_coupon_checkout)'
CREATE TABLE atlys_dataset.coupon_entered (`id` FixedString(32) COMMENT 'event id, 32-char hex' CODEC(ZSTD(1)), `timestamp` DateTime64(3, 'UTC') COMMENT 'event time, ms precision' CODEC(Delta(8), ZSTD(1)), `device_type` LowCardinality(String) COMMENT 'ios/Desktop/web-user-b2c/android, 4 values', `os` LowCardinality(String) DEFAULT '' COMMENT '5 values; 7.3% empty, bucket as unknown', `app_version` LowCardinality(String) COMMENT '3 values', `geoip_country_code` LowCardinality(String) COMMENT '7 values', `city` LowCardinality(String) COMMENT '7 values', `client_lib` LowCardinality(String) COMMENT 'mobile-rn or web-js', `user_id` String COMMENT 'traveller id, 28 chars, joins all tables' CODEC(ZSTD(1)), `application_id` FixedString(32) COMMENT 'funnel join key across coupon events' CODEC(ZSTD(1)), `destination` LowCardinality(String) COMMENT '14 values, ISO-2 uppercase', `cart_value` Decimal(18, 2) COMMENT 'cart total in accompanying currency, range 1509-8997', `currency` LowCardinality(String) COMMENT '7 values, never aggregate across currencies', `coupon_code` LowCardinality(String) COMMENT 'code submitted, 6 values, never null here', INDEX idx_user_id user_id TYPE bloom_filter(0.01) GRANULARITY 4) ENGINE = SharedMergeTree('/clickhouse/tables/{uuid}/{shard}', '{replica}') PARTITION BY toYYYYMM(timestamp) ORDER BY (device_type, destination, coupon_code, application_id, timestamp) SETTINGS index_granularity = 8192 COMMENT 'coupon_entered: user submits a code, funnel step 2 (spec 06_coupon_checkout)'
CREATE TABLE atlys_dataset.coupon_applied (`id` FixedString(32) COMMENT 'event id, 32-char hex' CODEC(ZSTD(1)), `timestamp` DateTime64(3, 'UTC') COMMENT 'event time, ms precision' CODEC(Delta(8), ZSTD(1)), `device_type` LowCardinality(String) COMMENT 'ios/Desktop/web-user-b2c/android, 4 values', `os` LowCardinality(String) DEFAULT '' COMMENT '5 values; 7.4% empty, bucket as unknown', `app_version` LowCardinality(String) COMMENT '3 values', `geoip_country_code` LowCardinality(String) COMMENT '7 values', `city` LowCardinality(String) COMMENT '7 values', `client_lib` LowCardinality(String) COMMENT 'mobile-rn or web-js', `user_id` String COMMENT 'traveller id, 28 chars, joins all tables' CODEC(ZSTD(1)), `application_id` FixedString(32) COMMENT 'funnel join key across coupon events' CODEC(ZSTD(1)), `destination` LowCardinality(String) COMMENT '14 values, ISO-2 uppercase', `cart_value` Decimal(18, 2) COMMENT 'cart total in accompanying currency, range 1546-8997', `currency` LowCardinality(String) COMMENT '7 values, never aggregate across currencies', `coupon_code` LowCardinality(String) COMMENT 'code validated, 5 values, never null here', `discount_type` LowCardinality(String) COMMENT 'percent or flat, 2 values', `discount_amount` Decimal(18, 2) COMMENT 'discount value in cart currency, range 0-1793', INDEX idx_user_id user_id TYPE bloom_filter(0.01) GRANULARITY 4) ENGINE = SharedMergeTree('/clickhouse/tables/{uuid}/{shard}', '{replica}') PARTITION BY toYYYYMM(timestamp) ORDER BY (device_type, destination, coupon_code, application_id, timestamp) SETTINGS index_granularity = 8192 COMMENT 'coupon_applied: code valid, discount computed, funnel step 3a (spec 06_coupon_checkout)'
CREATE TABLE atlys_dataset.discount_shown (`id` FixedString(32) COMMENT 'event id, 32-char hex' CODEC(ZSTD(1)), `timestamp` DateTime64(3, 'UTC') COMMENT 'event time, ms precision' CODEC(Delta(8), ZSTD(1)), `device_type` LowCardinality(String) COMMENT 'ios/Desktop/web-user-b2c/android, 4 values', `os` LowCardinality(String) DEFAULT '' COMMENT '5 values; 7.4% empty, bucket as unknown', `app_version` LowCardinality(String) COMMENT '3 values', `geoip_country_code` LowCardinality(String) COMMENT '7 values', `city` LowCardinality(String) COMMENT '7 values', `client_lib` LowCardinality(String) COMMENT 'mobile-rn or web-js', `user_id` String COMMENT 'traveller id, 28 chars, joins all tables' CODEC(ZSTD(1)), `application_id` FixedString(32) COMMENT 'funnel join key across coupon events' CODEC(ZSTD(1)), `destination` LowCardinality(String) COMMENT '14 values, ISO-2 uppercase', `cart_value` Decimal(18, 2) COMMENT 'cart total in accompanying currency, range 1546-8997', `currency` LowCardinality(String) COMMENT '7 values, never aggregate across currencies', `coupon_code` LowCardinality(String) COMMENT 'code applied, 5 values, never null here', `discount_amount` Decimal(18, 2) COMMENT 'discount value shown to user, range 0-1793', INDEX idx_user_id user_id TYPE bloom_filter(0.01) GRANULARITY 4) ENGINE = SharedMergeTree('/clickhouse/tables/{uuid}/{shard}', '{replica}') PARTITION BY toYYYYMM(timestamp) ORDER BY (device_type, destination, coupon_code, application_id, timestamp) SETTINGS index_granularity = 8192 COMMENT 'discount_shown: discounted price displayed, funnel step 3b (spec 06_coupon_checkout)'
CREATE TABLE atlys_dataset.coupon_rejected (`id` FixedString(32) COMMENT 'event id, 32-char hex' CODEC(ZSTD(1)), `timestamp` DateTime64(3, 'UTC') COMMENT 'event time, ms precision' CODEC(Delta(8), ZSTD(1)), `device_type` LowCardinality(String) COMMENT 'ios/Desktop/web-user-b2c/android, 4 values', `os` LowCardinality(String) DEFAULT '' COMMENT '5 values; 7.1% empty, bucket as unknown', `app_version` LowCardinality(String) COMMENT '3 values', `geoip_country_code` LowCardinality(String) COMMENT '7 values', `city` LowCardinality(String) COMMENT '7 values', `client_lib` LowCardinality(String) COMMENT 'mobile-rn or web-js', `user_id` String COMMENT 'traveller id, 28 chars, joins all tables' CODEC(ZSTD(1)), `application_id` FixedString(32) COMMENT 'funnel join key across coupon events' CODEC(ZSTD(1)), `destination` LowCardinality(String) COMMENT '14 values, ISO-2 uppercase', `cart_value` Decimal(18, 2) COMMENT 'cart total in accompanying currency, range 1509-8973', `currency` LowCardinality(String) COMMENT '7 values, never aggregate across currencies', `coupon_code` LowCardinality(String) COMMENT 'code that was rejected, 6 values, never null here', `reject_reason` LowCardinality(String) COMMENT 'invalid_code/min_cart_not_met/expired/already_used, 4 values', INDEX idx_user_id user_id TYPE bloom_filter(0.01) GRANULARITY 4) ENGINE = SharedMergeTree('/clickhouse/tables/{uuid}/{shard}', '{replica}') PARTITION BY toYYYYMM(timestamp) ORDER BY (device_type, destination, coupon_code, reject_reason, application_id, timestamp) SETTINGS index_granularity = 8192 COMMENT 'coupon_rejected: code invalid, funnel step 3c (spec 06_coupon_checkout)'
CREATE TABLE atlys_dataset.checkout_with_coupon (`id` FixedString(32) COMMENT 'event id, 32-char hex' CODEC(ZSTD(1)), `timestamp` DateTime64(3, 'UTC') COMMENT 'event time, ms precision' CODEC(Delta(8), ZSTD(1)), `device_type` LowCardinality(String) COMMENT 'ios/Desktop/web-user-b2c/android, 4 values', `os` LowCardinality(String) DEFAULT '' COMMENT '5 values; 6.2% empty, bucket as unknown', `app_version` LowCardinality(String) COMMENT '3 values', `geoip_country_code` LowCardinality(String) COMMENT '7 values', `city` LowCardinality(String) COMMENT '7 values', `client_lib` LowCardinality(String) COMMENT 'mobile-rn or web-js', `user_id` String COMMENT 'traveller id, 28 chars, joins all tables' CODEC(ZSTD(1)), `application_id` FixedString(32) COMMENT 'funnel join key across coupon events' CODEC(ZSTD(1)), `destination` LowCardinality(String) COMMENT '14 values, ISO-2 uppercase', `cart_value` Decimal(18, 2) COMMENT 'cart total in accompanying currency, range 1502-9000', `currency` LowCardinality(String) COMMENT '7 values, never aggregate across currencies', `coupon_code` LowCardinality(String) DEFAULT '' COMMENT '6 values; 62.9% empty = genuine no-coupon baseline, not missing data', `discount_amount` Decimal(18, 2) COMMENT 'discount applied at checkout, 0 for no-coupon rows, range 0-1768', `final_value` Decimal(18, 2) COMMENT 'amount charged after discount, range 1286-9000', INDEX idx_user_id user_id TYPE bloom_filter(0.01) GRANULARITY 4) ENGINE = SharedMergeTree('/clickhouse/tables/{uuid}/{shard}', '{replica}') PARTITION BY toYYYYMM(timestamp) ORDER BY (device_type, destination, coupon_code, application_id, timestamp) SETTINGS index_granularity = 8192 COMMENT 'checkout_with_coupon: checkout proceeds, conversion event; coupon_code empty = no-coupon baseline (spec 06_coupon_checkout)'